import{_ as r,a0 as s,w as l,s as m,ao as i,I as a,x as p,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"Nmap--不是隻能用於做壞事！ | LCTT x X-CMD","titleTemplate":false,"description":"Nmap--不是隻能用於做壞事！ | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Nmap--不是隻能用於做壞事！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Nmap--不是隻能用於做壞事！ | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150306 Nmap--Not Just for Evil","title":"Nmap--不是隻能用於做壞事！","tag":"201504","desc":""},"relativePath":"201504/20150306 Nmap--Not Just for Evil.md","filePath":"[post].md"}'),u={name:"201504/20150306 Nmap--Not Just for Evil.md"};function d(f,t,N,T,w,x){const o=s("Link");return l(),m("div",null,[t[13]||(t[13]=i(`<h1 id="nmap-不是隻能用於做壞事" tabindex="-1">Nmap--不是隻能用於做壞事！ <a class="header-anchor" href="#nmap-不是隻能用於做壞事" aria-label="Permalink to “Nmap--不是隻能用於做壞事！”">​</a></h1><p>如果SSH是系統管理員世界的&quot;瑞士軍刀&quot;的話，那麼Nmap就是一盒炸藥。炸藥很容易被誤用然後將你的雙腳崩掉，但是也是一個很有威力的工具，能夠勝任一些看似無法完成的任務。</p><p>大多數人想到Nmap時，他們想到的是掃描服務器，查找開放端口來實施攻擊。然而，在過去的這些年中，這樣的超能力在當你管理服務器或計算機遇到問題時也是非常的有用。無論是你試圖找出在你的網絡上有哪些類型的服務器使用了指定的IP地址，或者嘗試鎖定一個新的NAS設備，以及掃描網絡等，都會非常有用。</p><p>下圖顯示了我的QNAP NAS的網絡掃描結果。我使用該設備的唯一目的是為了NFS和SMB文件共享，但是你可以看到，它包含了一大堆大開大敞的端口。如果沒有Nmap，很難發現機器到底在運行着什麼玩意兒。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1002061/11825nmapf1.jpg" alt=""></p><p><em>網絡掃描</em></p><p>另外一個可能你沒想到的用途是用它來掃描一個網絡。你甚至根本不需要root的訪問權限，而且你也可以非常容易地來指定你想要掃描的網絡地址塊，例如輸入：</p><pre><code>nmap 192.168.1.0/24
</code></pre><p>上述命令會掃描我的局域網中全部的254個可用的IP地址，讓我可以知道那個是可以Ping的，以及那些端口是開放的。如果你剛剛在網絡上添加一個新的硬件，但是不知道它通過DHCP獲取的IP地址是什麼，那麼此時Nmap就是無價之寶。例如，上述命令在我的網絡中揭示了這個問題：</p><pre><code>Nmap scan report for TIVO-8480001903CCDDB.brainofshawn.com (192.168.1.220)
Host is up (0.0083s latency).
Not shown: 995 filtered ports
PORT     STATE  SERVICE
80/tcp   open   http
443/tcp  open   https
2190/tcp open   tivoconnect
2191/tcp open   tvbus
9080/tcp closed glrpc
</code></pre><p>它不僅顯示了新的Tivo 設備，而且還告訴我那些端口是開放的。由於它的可靠性、可用性以及“黑邊帽子”的能力，Nmap獲得了本月的 &lt;&lt;編輯推薦&gt;&gt;獎。這不是一個新的程序，但是如果你是一個linux用户的話，你應該玩玩它。</p><hr>`,12)),a("p",null,[t[1]||(t[1]=p("via: ",-1)),e(o,{href:"http://www.linuxjournal.com/content/nmap%E2%80%94not-just-evil"},{default:n(()=>[...t[0]||(t[0]=[p("http://www.linuxjournal.com/content/nmap—not-just-evil",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=p("作者：",-1)),e(o,{href:"http://www.linuxjournal.com/users/shawn-powers"},{default:n(()=>[...t[2]||(t[2]=[p("Shawn Powers",-1)])]),_:1}),t[6]||(t[6]=p(" 譯者：",-1)),e(o,{href:"https://github.com/theo-l"},{default:n(()=>[...t[3]||(t[3]=[p("theo-l",-1)])]),_:1}),t[7]||(t[7]=p(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[p("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=p("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[p("LCTT",-1)])]),_:1}),t[11]||(t[11]=p(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[p("Linux中國",-1)])]),_:1}),t[12]||(t[12]=p(" 榮譽推出",-1))])])}const S=r(u,[["render",d]]);export{P as __pageData,S as default};
